    child: React.ReactNode | undefined,
    tagName: keyof React.JSX.IntrinsicElements = "span",
    props: React.HTMLProps<HTMLElement> = {},
) {
    if (child == null || typeof child === "boolean" || isEmptyString(child)) {
        return undefined;
    } else if (
        typeof child === "string" ||
        typeof child === "number" ||
        isReactFragment(child) ||
        isReactNodeArray(child)
    ) {
        // wrap the child element
        return createElement(tagName, props, child);
    } else if (isReactElement(child)) {
        if (Object.keys(props).length > 0) {
            // clone the element and merge props
            return cloneElement(child, props);
        } else {
            // nothing to do, it's a valid ReactElement
            return child;
        }
    } else {
        // child is inferred as {}
        return undefined;
    }
}

export function isReactElement<T = any>(child: React.ReactNode): child is React.ReactElement<T> {
    return (
        typeof child === "object" &&
        typeof (child as any).type !== "undefined" &&
        typeof (child as any).props !== "undefined"
    );
}

function isReactFragment(child: React.ReactNode): child is Iterable<React.ReactNode> {
    // bit hacky, but generally works
    return typeof (child as any).type === "symbol";
}

function isReactNodeArray(child: React.ReactNode): child is React.ReactNode[] {
    return Array.isArray(child);
}

/**
 * Returns true if the given JSX element matches the given component type.
 *
 * NOTE: This function only checks equality of `displayName` for performance and
 * to tolerate multiple minor versions of a component being included in one
 * application bundle.
 *
 * @param element JSX element in question
 * @param ComponentType desired component type of element
 */
// eslint-disable-next-line @typescript-eslint/no-empty-object-type
export function isElementOfType<P = {}>(
    element: any,
    ComponentType: React.ComponentType<P>,
): element is React.ReactElement<P> {
    return (
        element != null &&
        element.type != null &&
        element.type.displayName != null &&
        element.type.displayName === ComponentType.displayName
    );
}

/** `displayName` prefix shared by every generated `@blueprintjs/icons` component (legacy and next). */
const BLUEPRINT_ICON_DISPLAYNAME_PREFIX = `${DISPLAYNAME_PREFIX}.Icon.`;

/**
 * Returns true if the given value is a Blueprint icon element (from `@blueprintjs/icons`, legacy or
 * next). Such elements accept the full `SVGIconProps` interface, so `size`/`color` may be safely
 * forwarded onto them. Recognition is by `displayName` prefix, consistent with `isElementOfType`,
 * which tolerates multiple minor versions of `@blueprintjs/icons` coexisting in one bundle. The
 * trailing dot excludes the `<Icon>` component itself (`Blueprint6.Icon`) and the SVG containers.
 */
export function isBlueprintIconElement(value: unknown): value is React.ReactElement<SVGIconProps> {
    if (!isValidElement(value)) {
        return false;
    }
    const { type } = value;
    if (typeof type === "string") {
        return false;
    }
    const { displayName } = type as { displayName?: unknown };
    return typeof displayName === "string" && displayName.startsWith(BLUEPRINT_ICON_DISPLAYNAME_PREFIX);
}

