    args: {
        intent: Intent.WARNING,
        icon: "warning-sign",
        children: "This is a warning intent alert.",
    },
};

/**
 * Danger intent alert.
 */
export const Danger: Story = {
    args: {
        intent: Intent.DANGER,
        icon: "error",
        children: "This is a danger intent alert.",
    },
};

/**
 * Alert with only a confirm button (no cancel).
 */
