    &::after {
      background: svg-icon(
        "16px/chevron-right.svg",
        (
          path: (
            fill: $pt-icon-color,
          ),
        )
      );
      content: "";
      display: block;
      height: $pt-icon-size-standard;
      margin: 0 $pt-spacing;
      width: $pt-icon-size-standard;
    }

    &:last-of-type::after {
      display: none;
