  margin-right: $pt-spacing * 0.5;
  padding: 1px $pt-spacing;
  vertical-align: text-bottom;

  &::before {
    background: svg-icon(
        "16px/more.svg",
        (
          path: (
            fill: $pt-icon-color,
          ),
        )
      )
      center no-repeat;
    content: "";
    display: block;
    height: $pt-icon-size-standard;
    width: $pt-icon-size-standard;
  }

