    bodyText?: string;
    intent?: React.ComponentProps<typeof Button>["intent"];
    buttonText?: string;
}) {
    return function Render(args: React.ComponentProps<typeof Dialog>) {
        const [, updateArgs] = useArgs();
        const handleOpen = useCallback(() => updateArgs({ isOpen: true }), [updateArgs]);
