        const intent = extraProps?.intent;
        const buttonText = extraProps?.buttonText ?? "Open Dialog";

        return (
            <>
                <Button text={buttonText} intent={intent} onClick={handleOpen} />
                <Dialog {...args} isOpen={args.isOpen} onClose={handleClose}>
                    <DialogBody>
                        <p>{bodyText}</p>
