    const {
        buttonText,
        className,
        disabled,
        fill,
        hasSelection = false,
        inputProps = {},
        // eslint-disable-next-line @typescript-eslint/no-deprecated
        large = false,
        onInputChange,
        size = "medium",
        // eslint-disable-next-line @typescript-eslint/no-deprecated
        small = false,
        text = "Choose file...",
        ...htmlProps
    } = props;

    const rootClasses = classNames(
        className,
        Classes.FILE_INPUT,
        {
            [Classes.DISABLED]: disabled,
            [Classes.FILL]: fill,
            [Classes.FILE_INPUT_HAS_SELECTION]: hasSelection,
        },
