    &.#{$ns}-active {
      @include focus-outline(0);
    }
  }

  .#{$ns}-input-ghost {
    // input fills remaining line
    flex: 1 1 auto;
    line-height: calc(var(--bp-surface-spacing) * 5);
    // essentially a min-width, cuz flex allows it to grow or shrink:
