                        >
                            {tag}
                        </CompoundTag>
                    ))}
                </Flex>
                {tags.length === 0 && (
                    <Button icon="refresh" variant="outlined" size="small" text="Reset tags" onClick={handleReset} />
                )}
            </Flex>
        );
    },
    args: {
        leftContent: "City",
        children: undefined,
        icon: "globe",
        endIcon: "map-marker",
        interactive: true,
    },
};

