import { Flex } from "@blueprintjs/labs";

import { Intent } from "../../common";

import { Tag } from "./tag";

// These props are deprecated on Tag — hide them from the Storybook controls panel.
const disabledArgs = ["large", "rightIcon", "children"] as const satisfies ReadonlyArray<
    keyof React.ComponentProps<typeof Tag>
>;

const meta: Meta<typeof Tag> = {
    title: "Core/Tag/Tag",
    component: Tag,
    decorators: [storybookLayoutDecorator],
    tags: ["autodocs"],
    args: {
        children: "Tag",
        intent: "none",
        size: "medium",
        icon: undefined,
        endIcon: undefined,
        fill: false,
        active: false,
        minimal: false,
        round: false,
        interactive: false,
    },
    argTypes: {
        intent: {
            control: "select",
            options: Object.values(Intent),
        },
        size: {
            control: "select",
            options: ["medium", "large"],
        },
        icon: {
            control: "text",
        },
        endIcon: {
            control: "text",
        },
        active: {
            control: "boolean",
        },
        fill: {
            control: "boolean",
        },
        interactive: {
            control: "boolean",
        },
        minimal: {
            control: "boolean",
        },
        multiline: {
            control: "boolean",
        },
        round: {
            control: "boolean",
        },
        onClick: { action: "clicked" },
        onRemove: { action: "removed" },
        ...disabledArgs.reduce(
            (acc, argName) => {
                acc[argName] = {
                    table: {
                        disable: true,
                    },
                };
                return acc;
            },
            {} as Record<(typeof disabledArgs)[number], { table: { disable: boolean } }>,
        ),
    },
} satisfies Meta<typeof Tag>;

export default meta;
type Story = StoryObj<typeof meta>;

/**
 * A basic tag with default styling.
 */
export const Default: Story = {
    args: {
        children: "Tag",
    },
};

/**
 * Use the `intent` prop to apply a semantic color that conveys the purpose or status of the tag.
 */
export const IntentExample: Story = {
    name: "Intent",
    argTypes: {
        intent: { table: { disable: true } },
    },
    render: args => (
        <Flex gap={2}>
            {Object.values(Intent)
                .filter(i => i !== "none")
                .map(intent => (
                    <Tag key={intent} {...args} intent={intent}>
                        {intent.charAt(0).toUpperCase() + intent.slice(1)}
                    </Tag>
                ))}
        </Flex>
    ),
};

/**
 * Use the `minimal` prop to render a tag with reduced visual weight, without a filled background.
 */
export const VariantExample: Story = {
    name: "Variant",
