};

/**
 * Use `icon` and `endIcon` props to render icons alongside the tag content.
 */
export const IconExample: Story = {
    name: "Icons",
    argTypes: {
        icon: { table: { disable: true } },
        endIcon: { table: { disable: true } },
    },
    render: args => (
        <Flex gap={2}>
            <Tag {...args} icon="home">
                Start icon
            </Tag>
            <Tag {...args} endIcon="map">
                End icon
            </Tag>
            <Tag {...args} icon="home" endIcon="map">
                Both
            </Tag>
