 */
export const ExpandNode: Story = {
    name: "Expand Node",
    ...Playground,
    play: async ({ canvas, userEvent, step }) => {
        await step("Collapsed folder hides children", async () => {
            await expect(canvas.queryByText("Nested Item 0")).toBeNull();
