     *
     * @default "en-US"
     */
    locale?: Locale | string;
}

export function getLocaleCodeFromProps(localeOrCode: DateFnsLocaleProps["locale"]): string | undefined {
    return typeof localeOrCode === "string" ? localeOrCode : localeOrCode?.code;
}

