        <div ref={popoverContentRef} role="dialog" aria-label="date picker" id={popoverId}>
            {/* eslint-disable-next-line jsx-a11y/no-noninteractive-tabindex */}
            <div onFocus={handleStartFocusBoundaryFocusIn} tabIndex={0} />
