/**
 * Takes the same arguments as `ItemRenderer<Film>`, but returns the common menu item
 * props for that item instead of the rendered element itself. This is useful for implementing
 * custom item renderers.
 */
export function getFilmItemProps(film: Film, itemProps: ItemRendererProps): Omit<MenuItemProps, "key"> {
    const { handleClick, handleFocus, modifiers, query, ref, id } = itemProps;
    return {
        active: modifiers.active,
        disabled: modifiers.disabled,
        id,
        label: film.year.toString(),
        onClick: handleClick,
        onFocus: handleFocus,
        ref,
        text: highlightText(`${film.rank}. ${film.title}`, query),
    };
}

/**
 * Simple film item renderer for "menu" containers. Does not support "selected" appearance.
 */
export const renderFilm: ItemRenderer<Film> = (film, props) => {
    if (!props.modifiers.matchesPredicate) {
        return null;
    }
    return <MenuItem key={film.rank} {...getFilmItemProps(film, props)} />;
};

